/// <summary>
/// MPJ_21275_BackOrders
/// Extension of CusTable form 
/// Customer Table Form COC
/// MPJ_21593 SVR document DCP 05/05/2022
/// </summary>
[ExtensionOf(formStr(CustTable))]
final class METCustTable_Form_Extension
{
}

Method.Source:
    /// <summary>
    /// Initilize form
    /// MPJ_21593 SVR document DCP 05/05/2022
    /// MPJ_21275_BackOrders
    /// Based on legal entity allow backorder parameter on customer mater level able to access the allow back order check box
    /// </summary>
    public void init()
    {
        CustParameters  custParameters  = CustParameters::find();
      
        next init();

        if (custParameters.METAllowBackOrders == NoYes::Yes)
        {
            BackOrders_AllowBackOrders.allowEdit(true);
        }
        else
        {
            BackOrders_AllowBackOrders.allowEdit(false);
        }
        metCustTable_ds.object(fieldNum(METCustTable, LoanValueNotDue)).enabled(false);
        metCustTable_ds.object(fieldNum(METCustTable, LoanValueNotDueDate)).enabled(false);
    }
